sys_script_include.script:
var getGroupMember = Class.create();
getGroupMember.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	grpMember: function () {
		var count = '';
		var groupName = this.getParameter('sysparm_assignment_group');
		var gr = new GlideRecord('sys_user_grmember');
		gr.addQuery('group', groupName);
		gr.query();

		if(gr.next()) {
			count = gr.getRowCount();
		} else {
			count = "There are no Members in the Group."
		}
		return count;

	},

	assignMembers : function () {
		var grMember = [];
		var groupID = this.getParameter('system_group_name');
		var gr = new GlideRecord('sys_user_grmember');
		gr.addQuery('group', groupID);
		gr.query();

		while(gr.next()) {
			var member = {};
			member.sys_id = gr.user.toString();
			member.name = gr.user.getDisplayValue();
			grMember.push(member);
		}
		return JSON.stringify(grMember); // Convert the grMember variable into a string, since the Answer variable/method only supports string data type
	},

	type: 'getGroupMember'
});
